#!/usr/bin/env python3
"""Emit absolute Linux TCP open and failure counters for one network namespace."""
import json
import os
import time
from pathlib import Path

COLLECTOR = "linux_tcp_open_counters_v1"


def emit(status, **fields):
    event = {
        "event_version": 1,
        "collector": COLLECTOR,
        "collector_status": status,
        "observed_at_epoch": int(time.time()),
    }
    event.update(fields)
    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)


def read_tcp_section(path):
    rows = [
        line.split()
        for line in Path(path).read_text(encoding="ascii").splitlines()
        if line.startswith("Tcp:")
    ]
    if len(rows) != 2 or len(rows[0]) != len(rows[1]):
        raise ValueError("invalid_tcp_table")
    return {name: int(value) for name, value in zip(rows[0][1:], rows[1][1:])}


try:
    tcp = read_tcp_section("/proc/net/snmp")
    boot_id = Path("/proc/sys/kernel/random/boot_id").read_text(encoding="ascii").strip()
    namespace_inode = os.stat("/proc/self/ns/net").st_ino
    names = {
        "tcp_active_opens_total": tcp.get("ActiveOpens"),
        "tcp_passive_opens_total": tcp.get("PassiveOpens"),
        "tcp_attempt_fails_total": tcp.get("AttemptFails"),
        "tcp_estab_resets_total": tcp.get("EstabResets"),
        "tcp_curr_estab": tcp.get("CurrEstab"),
    }
    missing = sorted(name for name, value in names.items() if value is None)
    if not boot_id or namespace_inode <= 0 or missing or any(value < 0 for value in names.values() if value is not None):
        emit(
            "contract_incomplete",
            boot_id=boot_id or None,
            network_namespace_inode=namespace_inode,
            missing_fields=missing,
        )
    else:
        emit(
            "ok",
            boot_id=boot_id,
            network_namespace_inode=namespace_inode,
            **names,
        )
except (OSError, UnicodeError, ValueError) as error:
    emit("read_error", error_type=type(error).__name__)
